     1	package hotel.reports;
     2	
     3	import hotel.reservations.Reservation;
     4	import hotel.reservations.ReservationStore;
     5	import java.math.BigDecimal;
     6	import java.time.YearMonth;
     7	import java.util.ArrayList;
     8	import java.util.Comparator;
     9	import java.util.List;
    10	
    11	/**
    12	 * The money the inn kept from the reservations that start in a given month, for the accountant (CSV).
    13	 * A cancelled non-refundable reservation counts: the guest paid and nothing went back.
    14	 */
    15	public final class RevenueReport {
    16	
    17	    private final ReservationStore store;
    18	
    19	    public RevenueReport(ReservationStore store) {
    20	        this.store = store;
    21	    }
    22	
    23	    public String generate(YearMonth month) {
    24	        List<Reservation> withRevenue = new ArrayList<>();
    25	        for (Reservation reservation : store.all()) {
    26	            boolean keptMoney = reservation.amountKept().signum() > 0;
    27	            boolean startsInMonth = YearMonth.from(reservation.checkIn()).equals(month);
    28	            if (keptMoney && startsInMonth) {
    29	                withRevenue.add(reservation);
    30	            }
    31	        }
    32	        withRevenue.sort(Comparator.comparing(Reservation::checkIn).thenComparingLong(Reservation::id));
    33	
    34	        StringBuilder csv = new StringBuilder();
    35	        csv.append("Pousada Maré Alta,revenue,").append(month).append('\n');
    36	        csv.append("reservation,room,check_in,check_out,status,amount\n");
    37	        BigDecimal revenue = BigDecimal.ZERO.setScale(2);
    38	        for (Reservation reservation : withRevenue) {
    39	            csv.append(reservation.id()).append(',')
    40	                    .append(reservation.roomNumber()).append(',')
    41	                    .append(reservation.checkIn()).append(',')
    42	                    .append(reservation.checkOut()).append(',')
    43	                    .append(reservation.status()).append(',')
    44	                    .append(reservation.amountKept().toPlainString()).append('\n');
    45	            revenue = revenue.add(reservation.amountKept());
    46	        }
    47	        csv.append("total,").append(revenue.toPlainString()).append('\n');
    48	        return csv.toString();
    49	    }
    50	}
=== reports/TourismTaxReport.java
     1	package hotel.reports;
     2	
     3	import hotel.reservations.Reservation;
     4	import hotel.reservations.ReservationStore;
     5	import java.math.BigDecimal;
     6	import java.time.YearMonth;
     7	import java.util.ArrayList;
     8	import java.util.Comparator;
     9	import java.util.List;
    10	
    11	/** The tourism tax the city charges: R$ 4,50 per guest per night, for the paid stays that start in the month. */
    12	public final class TourismTaxReport {
    13	
    14	    static final BigDecimal TAX_PER_GUEST_PER_NIGHT = new BigDecimal("4.50");
    15	
    16	    private final ReservationStore store;
    17	
    18	    public TourismTaxReport(ReservationStore store) {
    19	        this.store = store;
    20	    }
    21	
    22	    public String generate(YearMonth month) {
    23	        List<Reservation> paidInMonth = new ArrayList<>();
    24	        for (Reservation reservation : store.all()) {
    25	            boolean startsInMonth = YearMonth.from(reservation.checkIn()).equals(month);
    26	            if (reservation.isPaid() && startsInMonth) {
    27	                paidInMonth.add(reservation);
    28	            }
    29	        }
    30	        paidInMonth.sort(Comparator.comparing(Reservation::checkIn).thenComparingLong(Reservation::id));
    31	
    32	        StringBuilder csv = new StringBuilder();
    33	        csv.append("Pousada Maré Alta,tourism-tax,").append(month).append('\n');
    34	        csv.append("reservation,room,check_in,check_out,guests,nights,tax\n");
    35	        BigDecimal totalTax = BigDecimal.ZERO.setScale(2);
    36	        for (Reservation reservation : paidInMonth) {
    37	            BigDecimal tax = TAX_PER_GUEST_PER_NIGHT.multiply(
    38	                    BigDecimal.valueOf((long) reservation.guests() * reservation.price().nights()));
    39	            csv.append(reservation.id()).append(',')
    40	                    .append(reservation.roomNumber()).append(',')
    41	                    .append(reservation.checkIn()).append(',')
    42	                    .append(reservation.checkOut()).append(',')
    43	                    .append(reservation.guests()).append(',')
    44	                    .append(reservation.price().nights()).append(',')
    45	                    .append(tax.toPlainString()).append('\n');
    46	            totalTax = totalTax.add(tax);
    47	        }
    48	        csv.append("total,").append(totalTax.toPlainString()).append('\n');
    49	        return csv.toString();
    50	    }
    51	}
