     1	package hotel.messages;
     2	
     3	import java.util.ArrayList;
     4	import java.util.List;
     5	
     6	/** Every message the inn sent, so the front desk can check what each guest received. */
     7	public final class SentMessages {
     8	
     9	    private final List<Message> messages = new ArrayList<>();
    10	
    11	    synchronized Message add(String channel, String to, String subject, String body) {
    12	        Message message = new Message(messages.size() + 1L, channel, to, subject, body);
    13	        messages.add(message);
    14	        return message;
    15	    }
    16	
    17	    public synchronized List<Message> all() {
    18	        return new ArrayList<>(messages);
    19	    }
    20	}
