    32	import hotel.reservations.ErrorCode;
    33	import hotel.reservations.Guest;
    34	import hotel.reservations.HotelException;
    35	import hotel.reservations.NewReservation;
    36	import hotel.reservations.ReservationService;
    37	import hotel.rooms.Rooms;
    38	import io.javalin.Javalin;
    39	import io.javalin.http.Context;
    40	import io.javalin.json.JavalinJackson;
    41	import java.time.LocalDate;
    42	import java.time.YearMonth;
    43	import java.time.format.DateTimeParseException;
    44	
    45	/** The HTTP API the inn's website and front desk call. */
    46	public final class HttpApi {
    47	
    48	    private final Javalin server;
    49	    private final Rooms rooms;
    50	    private final ReservationService reservations;
    51	    private final SentMessages sentMessages;
    52	    private final OccupancyReport occupancyReport;
    53	    private final RevenueReport revenueReport;
    54	    private final TourismTaxReport tourismTaxReport;
    55	    private final RatePlanReport ratePlanReport;
    56	
    57	    public HttpApi(
    58	            Rooms rooms,
    59	            ReservationService reservations,
    60	            SentMessages sentMessages,
    61	            OccupancyReport occupancyReport,
    62	            RevenueReport revenueReport,
    63	            TourismTaxReport tourismTaxReport,
    64	            RatePlanReport ratePlanReport) {
    65	        this.rooms = rooms;
    66	        this.reservations = reservations;
    67	        this.sentMessages = sentMessages;
    68	        this.occupancyReport = occupancyReport;
    69	        this.revenueReport = revenueReport;
    70	        this.tourismTaxReport = tourismTaxReport;
    71	        this.ratePlanReport = ratePlanReport;
    72	
    73	        ObjectMapper jsonMapper = JsonMapper.builder()
    74	                .addModule(new JavaTimeModule())
    75	                .disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS)
    76	                .build();
    77	        this.server = Javalin.create(config -> {
    78	            config.showJavalinBanner = false;
    79	            config.jsonMapper(new JavalinJackson(jsonMapper, false));
    80	        });
    81	        registerRoutes();
    82	        registerErrorHandling();
    83	    }
    84	
    85	    public Javalin server() {
    86	        return server;
    87	    }
    88	
    89	    private void registerRoutes() {
    90	        server.get("/rooms", ctx -> ctx.json(rooms.all()));
    91	
    92	        server.post("/reservations", ctx -> {
    93	            NewReservation request = readNewReservation(ctx);
    94	            ctx.status(201).json(new ReservationResponse(reservations.create(request)));
    95	        });
    96	        server.get("/reservations/{id}", ctx ->
    97	                ctx.json(new ReservationResponse(reservations.find(reservationId(ctx)))));
    98	        server.post("/reservations/{id}/confirmation", ctx ->
    99	                ctx.json(new ReservationResponse(reservations.confirm(reservationId(ctx)))));
   100	        server.post("/reservations/{id}/cancellation", ctx ->
   101	                ctx.json(new ReservationResponse(reservations.cancel(reservationId(ctx)))));
   102	        server.post("/reservations/{id}/check-in", ctx ->
   103	                ctx.json(new ReservationResponse(reservations.checkIn(reservationId(ctx)))));
   104	        server.post("/reservations/{id}/check-out", ctx ->
   105	                ctx.json(reservations.checkOut(reservationId(ctx))));
   106	        server.get("/reservations/{id}/document", ctx ->
   107	                ctx.json(reservations.receiptCopy(reservationId(ctx))));
   108	
   109	        server.get("/messages", ctx -> ctx.json(sentMessages.all()));
   110	
   111	        server.get("/reports/occupancy", ctx -> {
   112	            LocalDate night = readDate(ctx);
   113	            ctx.contentType("text/csv; charset=utf-8").result(occupancyReport.generate(night));
   114	        });
   115	        server.get("/reports/revenue", ctx -> {
   116	            YearMonth month = readMonth(ctx);
   117	            ctx.contentType("text/csv; charset=utf-8").result(revenueReport.generate(month));
   118	        });
   119	        server.get("/reports/tourism-tax", ctx -> {
   120	            YearMonth month = readMonth(ctx);
   121	            ctx.contentType("text/csv; charset=utf-8").result(tourismTaxReport.generate(month));
   122	        });
   123	        server.get("/reports/rate-plans", ctx -> {
   124	            YearMonth month = readMonth(ctx);
   125	            ctx.contentType("text/csv; charset=utf-8").result(ratePlanReport.generate(month));
   126	        });
   127	    }
   128	
   129	    private void registerErrorHandling() {
   130	        server.exception(HotelException.class, (exception, ctx) -> {
   131	            ctx.status(httpStatus(exception.errorCode()));
   132	            ctx.json(new ErrorResponse(exception.errorCode().name(), exception.getMessage()));
   133	        });
   134	    }
   135	
   136	    private static int httpStatus(ErrorCode errorCode) {
   137	        return switch (errorCode) {
   138	            case INVALID_REQUEST -> 400;
   139	            case ROOM_NOT_FOUND, RESERVATION_NOT_FOUND -> 404;
   140	            case ROOM_UNAVAILABLE, OPERATION_NOT_ALLOWED -> 409;
   141	            case CAPACITY_EXCEEDED -> 422;
   142	        };
   143	    }
   144	
   145	    private static NewReservation readNewReservation(Context ctx) {
   146	        CreateReservationRequest body;
   147	        try {
   148	            body = ctx.bodyAsClass(CreateReservationRequest.class);
   149	        } catch (Exception unreadableBody) { // Jackson's own exceptions are checked, but reach here unwrapped
   150	            throw new HotelException(ErrorCode.INVALID_REQUEST, "the body is not a valid reservation request");
   151	        }
   152	        if (body == null
   153	                || body.roomNumber() == null
   154	                || isBlank(body.guestName())
   155	                || isBlank(body.guestEmail())
   156	                || isBlank(body.guestCpf())
   157	                || body.checkIn() == null
   158	                || body.checkOut() == null
   159	                || body.guests() == null
   160	                || body.ratePlan() == null) {
   161	            throw new HotelException(ErrorCode.INVALID_REQUEST, "every field of the reservation is required");
   162	        }
   163	        Guest guest = new Guest(body.guestName(), body.guestEmail(), body.guestCpf());
   164	        return new NewReservation(
   165	                body.roomNumber(), guest, body.checkIn(), body.checkOut(), body.guests(), body.ratePlan());
